 static string Hash(Mesh[] meshes){using(var stream=new MemoryStream()){using(var writer=new BinaryWriter(stream)){foreach(var m in meshes){if(m.vertexCount==0)continue;writer.Write(m.subMeshCount);var v=m.vertices;var n=m.normals;for(int sub=0;sub<m.subMeshCount;sub++){var ids=m.GetTriangles(sub);writer.Write(ids.Length);foreach(int i in ids){writer.Write(v[i].x);writer.Write(v[i].y);writer.Write(v[i].z);writer.Write(n[i].x);writer.Write(n[i].y);writer.Write(n[i].z);}}}writer.Flush();using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(stream.ToArray())).Replace("-","").ToLowerInvariant();}}}
 [UnityTest]public IEnumerator PreparedPartsKeepFrozenTriangleNormalsAndContactHeights(){
  foreach(var group in Cases.GroupBy(r=>r.Path)){
   var host=new GameObject("isolated frozen prepared surfaces");var visual=host.AddComponent<SampleVisual>();
   try{visual.Show(AssetDatabase.LoadAssetAtPath<VisualSampleAsset>(group.Key));yield return null;visual.Warm();
    foreach(var cuts in group.GroupBy(r=>r.X)){
     visual.Prepare(cuts.Key);visual.Animate(1,0);
     Assert.That(visual.SectionTop,Is.EqualTo(cuts.Max(r=>r.Top)),group.Key+" contact "+cuts.Key);
     foreach(var row in cuts){var side=row.Left?visual.Left:visual.Right;var meshes=side.GetComponentsInChildren<MeshFilter>(true).Where(v=>v.GetComponent<MeshRenderer>().enabled).Select(v=>v.sharedMesh).ToArray();Assert.That(Hash(meshes),Is.EqualTo(row.Hash),row.Path+" "+row.X+" left="+row.Left);Assert.That(side.localPosition.y,Is.EqualTo(row.Rest).Within(.000001f),"Frozen tray height");}
     visual.ResetAttempt();yield return null;
    }
   }finally{UnityEngine.Object.Destroy(host);}yield return null;
  }
 }
